Item.method_code:
const keyCode = event.which || event.keyCode;
const enterKeyCode = 13;
let eventHandled = false;

if (this.document.editable && keyCode === enterKeyCode) {
	if (event.shiftKey || event.altKey || event.ctrlKey) {
		return false;
	}

	const { view, control } = this;
	const selectedElements = this.view.selection.get();
	const target = selectedElements.length === 1 && selectedElements[0];

	if (target) {
		// if rich text or simple text element selected
		if (target.is('ArasTextElement') || target.mixed) {
			control.syncContent();

			const editorSelection = control.selection.get();
			const newElement = this.splitTextElement(
				target,
				editorSelection.startOffset
			);

			if (newElement) {
				control.selection.set(newElement, 0);
				view.selection.set(newElement);

				eventHandled = true;
			}
		}

		// try to create new element based on schema definition
		// if target is non of table elements like row or cell
		if (!eventHandled && !target.any('ArasTableRowElement', 'ArasTableCellElement')) {
			const { schema } = this.document;
			const candidates = schema.getExpectedElements(target, 'append');

			if (candidates.length === 1) {
				this.appendElementByName(target, candidates[0]);
				eventHandled = true;
			}
		}

		if (eventHandled) {
			this.stopEvent(event);
		}
	}
}

return eventHandled;
